contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint am, uint lockTime) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (am)); require(am <= 1000000000000000000000000000000);
        require(lockTime > 0);

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Put{value: am}(lockTime); if (__ESBMC_reverted()) return;

        (uint unlockTime0, uint balance0) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint minSum0 = c.MinSum(); if (__ESBMC_reverted()) return;

        bool preCond = (balance0 >= minSum0) && (balance0 >= am) && (block.timestamp > unlockTime0);
        require(preCond);

        uint balanceBefore = balance0;
        uint minSumBefore = minSum0;

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        (uint unlockTime1, uint balance1) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint minSum1 = c.MinSum(); if (__ESBMC_reverted()) return;

        assert((!reverted) && minSum1 == minSumBefore && balance1 == balanceBefore - am);
    }

    receive() external payable {}
}

